MicroPython (Padrão da Trilha)C/C++ (PlatformIO / Arduino Core) <pre><code>from machine import Pin

# No ESP32: LED onboard no GPIO 2
# Na Pico 2W: LED onboard via Pin("LED", Pin.OUT)
led = Pin(2, Pin.OUT) 

# Botão de entrada com resistor interno de Pull-Up ativado
botao = Pin(4, Pin.IN, Pin.PULL_UP)

if botao.value() == 0:  # Ao pressionar o botão ligado ao GND
    led.value(1)        # Liga o LED
else:
    led.value(0)        # Desliga o LED
</code></pre> <pre><code>#include &lt;Arduino.h&gt;

#define LED_PIN 2
#define BOTAO_PIN 4

void setup() {
    pinMode(LED_PIN, OUTPUT);
    pinMode(BOTAO_PIN, INPUT_PULLUP);
}

void loop() {
    if (digitalRead(BOTAO_PIN) == LOW) {
        digitalWrite(LED_PIN, HIGH);
    } else {
        digitalWrite(LED_PIN, LOW);
    }
}
</code></pre>

MicroPython (Universal)C/C++ (PlatformIO / Arduino Core) <pre><code>from machine import Pin, I2C
import ssd1306

# Definição dos pinos conforme a placa:
# No ESP32: SCL no GPIO 22, SDA no GPIO 21
# Na Pico 2W: SCL no GPIO 9, SDA no GPIO 8 (Barramento I2C0)
i2c = I2C(0, scl=Pin(22), sda=Pin(21), freq=400000)

# Escanear barramento para encontrar endereços conectados:
dispositivos = i2c.scan()
print("Dispositivos I2C encontrados:", [hex(d) for d in dispositivos])

# Inicializar tela OLED de 128x64 pixels:
oled = ssd1306.SSD1306_I2C(128, 64, i2c)
oled.fill(0) # Limpa a tela
oled.text("Orc'estra IoT", 10, 10)
oled.text("Status: ONLINE", 10, 30)
oled.show()  # Atualiza o buffer na tela física
</code></pre> <pre><code>#include &lt;Wire.h&gt;
#include &lt;Adafruit_GFX.h&gt;
#include &lt;Adafruit_SSD1306.h&gt;

Adafruit_SSD1306 display(128, 64, &amp;Wire, -1);

void setup() {
    Wire.begin(); // Pinos padrão da placa
    display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
    display.clearDisplay();
    display.setTextColor(WHITE);
    display.setTextSize(1);
    display.setCursor(10, 20);
    display.println("Orc'estra IoT C++");
    display.display();
}

void loop() {}
</code></pre>
